# Convention checks (CONTRIBUTING §3 and §5). Sourced by ci.yml and .githooks/commit-msg.

# Commit subject: type(scope)!: description, lowercase, no trailing period.
COMMIT_SUBJECT='^(feat|fix|refactor|docs|test|chore|perf|ci|build)(\([a-z0-9._/-]+\))?!?: [a-z0-9`].*[^.]$'

# Work branch: <type>/<issue>-<description> in kebab-case; only work without an Issue omits the number.
BRANCH_NAME='^(feature|fix|refactor|docs|test|chore)/([0-9]+-)?[a-z0-9]+(-[a-z0-9]+)*$'

# Returns 0 when the subject follows Conventional Commits. Commits generated by git (fixup, revert) are accepted.
check_subject() {
  local subject=$1
  case "$subject" in
    'fixup! '*|'squash! '*|'Revert "'*) return 0 ;;
  esac
  grep -qE "$COMMIT_SUBJECT" <<< "$subject"
}

check_branch() {
  grep -qE "$BRANCH_NAME" <<< "$1"
}
